 private void remember(View v){if(v instanceof TextView)fonts.put((TextView)v,((TextView)v).getTextSize());if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)remember(((ViewGroup)v).getChildAt(i));}
 void metrics(ServerStats stats){
  info.trust(stats);
  int batteryLevel=-1;try{batteryLevel=Integer.parseInt(stats.battery.replace("%",""));}catch(Exception ignored){}batteryGauge.level(batteryLevel);((CompactMetricCard)battery).indicator.setProgress(Math.max(0,Math.min(100,batteryLevel)));
  storageDetail.setText(stats.totalBytes>=0&&stats.freeBytes>=0?"свободно":"Объём недоступен");
  ((CompactMetricCard)storage).capacity.setText(stats.totalBytes>=0?"Всего "+SurfaceStyle.quantity(ServerTelemetry.bytes(stats.totalBytes)):"");
  storageUsed.setText(stats.totalBytes>=0&&stats.freeBytes>=0?"Занято "+SurfaceStyle.quantity(ServerTelemetry.bytes(Math.max(0,stats.totalBytes-stats.freeBytes)))+" ("+(int)Math.round(Math.max(0,Math.min(100,(stats.totalBytes-stats.freeBytes)*100d/Math.max(1,stats.totalBytes))))+"%)":"");
  ((CompactMetricCard)battery).artworkLevel(batteryLevel);
  usage.setProgress(stats.totalBytes>0&&stats.freeBytes>=0?(int)Math.round(Math.max(0,Math.min(100,(stats.totalBytes-stats.freeBytes)*100d/stats.totalBytes))):0);
  ((CompactMetricCard)storage).artworkLevel(stats.totalBytes>0&&stats.freeBytes>=0?usage.getProgress():-1);
  ((CompactMetricCard)battery).footer.setText("Заряжается".equals(stats.charging)?"Питание подключено":"От батареи".equals(stats.charging)?"Питание от батареи":"");
  charge.setText(stats.charging);charge.setTextColor(ThemeCatalog.color(getContext(),"Заряжается".equals(stats.charging)?com.bitpoint.homeservercontrol.ui.R.attr.hscSuccess:com.bitpoint.homeservercontrol.ui.R.attr.hscTextSecondary));lastMeasured=stats.telemetryAvailable?android.os.SystemClock.elapsedRealtime():0;updated.setText(stats.telemetryAvailable?"Обновлено сейчас":"Показатели недоступны");requestLayout();
 }
